begin;
set local lock_timeout='5s';
set local statement_timeout='60s';
-- Requires the reconciled public schema and all earlier migrations. Never push
-- this ledger to an unknown remote database without a schema diff and backup.
create schema if not exists krow_pilot;
revoke all on schema krow_pilot from public, anon, authenticated;

create table krow_pilot.tracking_sessions (
  ride_id uuid primary key references public.rides(ride_id) on delete cascade,
  session_id uuid not null unique default gen_random_uuid(),
  actor_id uuid not null references auth.users(id),
  device_id uuid not null,
  token_hash text not null,
  expires_at timestamptz not null,
  last_seq bigint not null default -1,
  position jsonb,
  updated_at timestamptz not null default now()
);
create table krow_pilot.messages (
  message_id uuid primary key default gen_random_uuid(),
  booking_id uuid not null references public.bookings(booking_id),
  sender_id uuid not null references auth.users(id),
  client_id uuid not null,
  body text not null check (length(trim(body)) between 1 and 2000),
  created_at timestamptz not null default now(),
  unique(booking_id, sender_id, client_id)
);
create index pilot_message_history on krow_pilot.messages(booking_id, created_at, message_id);
create table krow_pilot.cash (
  booking_id uuid primary key references public.bookings(booking_id),
  amount_cents integer not null check(amount_cents >= 0),
  status text not null default 'pending' check(status in ('pending','collected','void')),
  collected_by uuid references auth.users(id),
  updated_at timestamptz not null default now()
);
create table krow_pilot.reviews (
  booking_id uuid not null references public.bookings(booking_id),
  author_id uuid not null references auth.users(id),
  review_id uuid not null unique references public.ride_reviews(review_id),
  primary key(booking_id, author_id)
);
create table krow_pilot.booking_prices (
  booking_id uuid primary key references public.bookings(booking_id),
  amount_cents integer not null check(amount_cents >= 0)
);
insert into krow_pilot.booking_prices
select b.booking_id, round(r.price_per_seat * 100)::integer * b.seats_reserved
from public.bookings b join public.rides r using(ride_id);
create function krow_pilot.capture_price() returns trigger language plpgsql security definer
set search_path = pg_catalog, public, krow_pilot as $$
begin
  insert into krow_pilot.booking_prices(booking_id, amount_cents)
  select new.booking_id, round(price_per_seat * 100)::integer * new.seats_reserved
  from public.rides where ride_id = new.ride_id;
  return new;
end; $$;
create trigger pilot_booking_price after insert on public.bookings
for each row execute function krow_pilot.capture_price();
revoke all on all functions in schema krow_pilot from public, anon, authenticated;
alter table krow_pilot.tracking_sessions enable row level security;
alter table krow_pilot.messages enable row level security;
alter table krow_pilot.cash enable row level security;
alter table krow_pilot.reviews enable row level security;
alter table krow_pilot.booking_prices enable row level security;
revoke all on all tables in schema krow_pilot from public, anon, authenticated;
-- Public business privileges are changed separately during API cutover.
-- See scripts/pilot-api-cutover.sql; keep legacy writes available until the
-- private API login is configured and the pilot backend is running.


commit;

begin;
set local lock_timeout='5s';
set local statement_timeout='60s';
create table krow_pilot.devices(
  device_id uuid primary key,
  actor_id uuid not null references auth.users(id),
  token_encrypted text not null,
  updated_at timestamptz not null default now()
);
create table krow_pilot.outbox(
  intent_id uuid primary key default gen_random_uuid(),
  event_key text not null,
  ride_id uuid not null references public.rides(ride_id),
  booking_id uuid references public.bookings(booking_id),
  recipient_id uuid not null references auth.users(id),
  kind text not null,
  expires_at timestamptz not null default now()+interval '15 minutes',
  attempts integer not null default 0,
  status text not null default 'pending' check(status in('pending','accepted','expired','failed')),
  next_at timestamptz not null default now(),
  lease_until timestamptz,
  unique(event_key,recipient_id)
);
create index pilot_outbox_pending on krow_pilot.outbox(next_at) where status='pending';
create function krow_pilot.booking_notification() returns trigger language plpgsql security definer
set search_path=pg_catalog,public,krow_pilot as $$
declare driver uuid;
begin
  select d.user_id into driver from public.rides r join public.driver_profiles d using(driver_id) where r.ride_id=new.ride_id;
  insert into krow_pilot.outbox(event_key,ride_id,booking_id,recipient_id,kind)
  select new.booking_id::text||':'||new.status, new.ride_id,new.booking_id,recipient,'booking'
  from (values(driver),(new.user_id)) as recipients(recipient)
  on conflict(event_key,recipient_id) do nothing;
  return new;
end; $$;
create trigger pilot_booking_notification after insert or update of status on public.bookings
for each row execute function krow_pilot.booking_notification();
create function krow_pilot.message_notification() returns trigger language plpgsql security definer
set search_path=pg_catalog,public,krow_pilot as $$
begin
  insert into krow_pilot.outbox(event_key,ride_id,booking_id,recipient_id,kind)
  select new.message_id::text,b.ride_id,b.booking_id,case when b.user_id=new.sender_id then d.user_id else b.user_id end,'chat'
  from public.bookings b join public.rides r using(ride_id) join public.driver_profiles d using(driver_id)
  where b.booking_id=new.booking_id;
  return new;
end; $$;
create trigger pilot_message_notification after insert on krow_pilot.messages
for each row execute function krow_pilot.message_notification();
alter table krow_pilot.devices enable row level security;
alter table krow_pilot.outbox enable row level security;
revoke all on all tables in schema krow_pilot from public,anon,authenticated;
revoke all on all functions in schema krow_pilot from public,anon,authenticated;


commit;

begin;
set local lock_timeout='5s';
set local statement_timeout='60s';
-- Add compatible status/index/closure structures before the API cutover.
-- Business permission changes live in scripts/pilot-api-cutover.sql and must
-- follow activation of the private API login and RIDE_PILOT_ENABLED.
alter table public.bookings drop constraint bookings_status_check;
alter table public.bookings add constraint bookings_status_check check
  (status in ('pending','confirmed','rejected','cancelled','in_progress','completed','no_show','interrupted'));
create index if not exists pilot_reviews_subject on public.ride_reviews(reviewee_id);
create index if not exists pilot_activity_passenger on public.bookings(user_id,status,ride_id);
create index if not exists pilot_activity_driver on public.rides(driver_id,status,departure_time,ride_id);
-- Account access closes immediately; approved retention and anonymization are
-- a separate operational processing step, never an invented default period.
create table krow_pilot.account_closure_requests (
  actor_id uuid primary key references auth.users(id),
  requested_at timestamptz not null default now(),
  status text not null default 'access_closed' check(status in ('access_closed','processed')),
  processed_at timestamptz
);
alter table krow_pilot.account_closure_requests enable row level security;
revoke all on krow_pilot.account_closure_requests from public,anon,authenticated;


commit;

-- Apply as migration owner. Assign a separately managed LOGIN to this group.
-- Never give the API a superuser, database-owner or Supabase service-role login.
begin;
do $$ begin
  if not exists(select 1 from pg_roles where rolname='krow_pilot_service') then
    create role krow_pilot_service nologin nosuperuser nocreatedb nocreaterole noinherit nobypassrls;
  end if;
end $$;
grant usage on schema public,krow_pilot to krow_pilot_service;
grant select on public.users,public.driver_profiles,public.vehicles,public.rides,public.bookings,public.ride_stops to krow_pilot_service;
grant update(status,version,updated_at,available_seats) on public.rides to krow_pilot_service;
grant update(status) on public.bookings to krow_pilot_service;
grant update(rating) on public.users,public.driver_profiles to krow_pilot_service;
grant update(is_active) on public.users to krow_pilot_service;
grant insert(uuid,email_address,full_name,institutional_id,academic_program,academic_period),
  update(email_address,full_name,institutional_id,academic_program,academic_period)
  on public.users to krow_pilot_service;
drop policy if exists krow_pilot_user_insert on public.users;
create policy krow_pilot_user_insert on public.users for insert to krow_pilot_service with check(true);
grant select,insert on public.ride_reviews to krow_pilot_service;
drop policy if exists pilot_service_reviews on public.ride_reviews;
create policy pilot_service_reviews on public.ride_reviews for select to krow_pilot_service using(true);
drop policy if exists pilot_service_review_insert on public.ride_reviews;
create policy pilot_service_review_insert on public.ride_reviews for insert to krow_pilot_service with check(true);
grant select,insert,update,delete on all tables in schema krow_pilot to krow_pilot_service;
grant execute on function public.create_ride_v2(jsonb),public.update_ride_v2(uuid,integer,jsonb),public.upsert_favorite_route(jsonb),public.request_booking_v2(jsonb),public.delete_favorite_route(uuid) to krow_pilot_service;
grant insert on public.ride_status_history to krow_pilot_service;
do $$ declare s text; begin
  s:=pg_get_serial_sequence('public.ride_status_history','id');
  if s is not null then execute format('grant usage on sequence %s to krow_pilot_service',s); end if;
  s:=pg_get_serial_sequence('public.users','id');
  if s is not null then execute format('grant usage on sequence %s to krow_pilot_service',s); end if;
end $$;
drop policy if exists pilot_service_history on public.ride_status_history;
create policy pilot_service_history on public.ride_status_history for insert to krow_pilot_service with check(true);
do $$ declare t text; begin
  foreach t in array array['users','driver_profiles','vehicles','rides','bookings','ride_stops'] loop
    execute format('drop policy if exists pilot_service_select on public.%I',t);
    execute format('create policy pilot_service_select on public.%I for select to krow_pilot_service using(true)',t);
  end loop;
  foreach t in array array['rides','bookings','users','driver_profiles'] loop
    execute format('drop policy if exists pilot_service_update on public.%I',t);
    execute format('create policy pilot_service_update on public.%I for update to krow_pilot_service using(true) with check(true)',t);
  end loop;
  for t in select tablename from pg_tables where schemaname='krow_pilot' loop
    execute format('drop policy if exists pilot_service_access on krow_pilot.%I',t);
    execute format('create policy pilot_service_access on krow_pilot.%I to krow_pilot_service using(true) with check(true)',t);
  end loop;
end $$;
commit;

-- Credential-free preparation for the API's dedicated login.
-- Password provisioning happens only through a private local TLS connection.
do $$
begin
  if not exists(select 1 from pg_roles where rolname='krow_pilot_service') then
    raise exception 'Apply the audited pilot permission group first';
  end if;
  if exists(select 1 from pg_roles where rolname='krow_pilot_runtime') then
    raise exception 'Runtime role already exists; review before altering it';
  end if;
end;
$$;

create role krow_pilot_runtime nologin inherit nosuperuser nocreatedb
  nocreaterole noreplication nobypassrls connection limit 12;
grant krow_pilot_service to krow_pilot_runtime with inherit true;
grant krow_pilot_service to krow_pilot_runtime with admin false;
grant krow_pilot_service to krow_pilot_runtime with set false;

-- Deploy with the pilot API's private /me and participant views. A mobile
-- client must not read another traveller's email or academic identifiers.
-- Full account fields are served only after API identity/ownership checks.
revoke select on public.users from public, anon, authenticated;
do $$
declare columns_sql text;
begin
  select string_agg(quote_ident(attname), ', ' order by attnum)
    into columns_sql
    from pg_attribute
    where attrelid = 'public.users'::regclass and attnum > 0 and not attisdropped;
  execute format('revoke select (%s) on public.users from public, anon, authenticated', columns_sql);
end $$;
grant select (uuid, full_name, profile_photo, rating) on public.users to authenticated;
drop policy if exists users_select_coplanners on public.users;
-- Keep the existing own-account policy; participant cards are returned by
-- the API, which exposes only the fields necessary for that reservation.

-- RLS does not protect TRUNCATE or REFERENCES. Neither these privileges nor
-- permission to create triggers is needed by an untrusted app client.
do $$
declare table_name text;
begin
  foreach table_name in array array[
    'users', 'driver_profiles', 'vehicles', 'rides', 'ride_stops',
    'bookings', 'favorite_routes', 'favorite_route_stops', 'transport_stops',
    'ride_reviews', 'ride_status_history', 'chats', 'chat_messages',
    'payment_methods', 'payments'
  ] loop
    if to_regclass('public.' || table_name) is not null then
      execute format('revoke truncate, references, trigger on public.%I from public, anon, authenticated', table_name);
    end if;
  end loop;
end $$;

-- Apply only when the private pilot API is configured and ready to take traffic.
-- This preserves the authenticated actor in RPCs while making the API the
-- only business writer. Old API/mobile versions cannot write after this step.
begin;
set local lock_timeout = '5s';
do $$ declare f regprocedure; t text; begin
  for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where n.nspname='public' and p.proname in
    ('create_ride','create_ride_v2','update_ride_v2','upsert_favorite_route','delete_favorite_route',
     'request_booking','request_booking_v2','update_booking_status',
     'start_ride','cancel_ride','complete_ride','complete_stop','submit_review') loop
    execute format('revoke execute on function %s from public,anon,authenticated',f);
  end loop;
  foreach t in array array['rides','bookings','ride_stops','favorite_routes','ride_reviews','driver_profiles','vehicles','users'] loop
    if to_regclass('public.'||t) is not null then
      execute format('revoke insert,update,delete on public.%I from anon,authenticated',t);
    end if;
  end loop;
end $$;
-- Profile edits cannot change approval, reputation or account closure.
grant insert(uuid,email_address,full_name,institutional_id,academic_program,academic_period,profile_photo),
  update(uuid,email_address,full_name,institutional_id,academic_program,academic_period,profile_photo)
  on public.users to authenticated;
commit;
